mapper.select:
select
    count(0)
from virtual_inventory vi

    ${params.sqlMap.default}
    and vi.is_deleted = false

        ${params.permissionSql}

select vi.sku_id as skuId, vi.warehouse_id as warehouseId, vi.virtual_warehouse_id as virtualWarehouseId from virtual_inventory vi left join virtual_warehouse vw on vi.virtual_warehouse_id = vw.id and vw.is_deleted = false
${params.sqlMap.default} and vi.is_deleted = false
${params.permissionSql}
group by vi.sku_id,vi.warehouse_id,vi.virtual_warehouse_id order by
${item.field} ${item.sort}
vi.sku_id

select vi.warehouse_id, vi.sku_id, vi.dict_inventory_status, COALESCE(inv.qty,0) as qty, COALESCE(vi.qty,0) as virtualQty, vi.virtual_warehouse_id from virtual_inventory vi left join ( select inv.sku_id,inv.warehouse_id,inv.dict_inventory_status,sum(qty) as qty from inventory inv where inv.is_deleted = false group by inv.sku_id,inv.warehouse_id,inv.dict_inventory_status ) inv on vi.sku_id = inv.sku_id and vi.warehouse_id = inv.warehouse_id and vi.dict_inventory_status = inv.dict_inventory_status
vi.is_deleted = false and vi.sku_id in
#{item}
and vi.virtual_warehouse_id in
#{item}

select count(0) from ( select vi.sku_id,vi.warehouse_id from virtual_inventory vi left join ( select inv.sku_id,inv.warehouse_id,inv.dict_inventory_status,sum(qty) as qty from inventory inv where inv.is_deleted = false and inv.dict_inventory_status = 'usable' group by inv.sku_id,inv.warehouse_id,inv.dict_inventory_status ) inv on vi.sku_id = inv.sku_id and vi.warehouse_id = inv.warehouse_id and vi.dict_inventory_status = inv.dict_inventory_status
vi.is_deleted = false
${params.permissionSql}
group by vi.sku_id,vi.warehouse_id having COALESCE(sum(vi.qty),0) > COALESCE(sum(inv.qty),0) ) a;

select vi.virtual_warehouse_id as virtualWarehouseId, COALESCE(sum(vi.qty),0) as virtualQty, (select COALESCE(sum(qty),0) from virtual_inventory where is_deleted = false and virtual_warehouse_id = vi.virtual_warehouse_id and sku_id = vi.sku_id and warehouse_id = vi.warehouse_id and dict_inventory_status = 'usable') as virtualUsableQty, (select COALESCE(sum(qty),0) from virtual_inventory where is_deleted = false and virtual_warehouse_id = vi.virtual_warehouse_id and sku_id = vi.sku_id and warehouse_id = vi.warehouse_id and dict_inventory_status = 'frozen') as virtualFrozenQty from virtual_inventory vi
vi.is_deleted = false and vi.sku_id = #{params.skuId} and vi.warehouse_id = #{params.warehouseId}
${params.permissionSql}
group by vi.virtual_warehouse_id,vi.sku_id,vi.warehouse_id order by
${item.field} ${item.sort}
vi.virtual_warehouse_id

select skuId,warehouseId,virtualWarehouseId,virtualQty,virtualUsableQty,virtualFrozenQty,usableQty from (select vi.sku_id as skuId, vi.warehouse_id as warehouseId, vi.virtual_warehouse_id as virtualWarehouseId, COALESCE(sum(vi.qty),0) as virtualQty, (select COALESCE(sum(qty),0) from virtual_inventory where is_deleted = false and sku_id = vi.sku_id and warehouse_id = vi.warehouse_id and virtual_warehouse_id = vi.virtual_warehouse_id and dict_inventory_status = 'usable') as virtualUsableQty, (select COALESCE(sum(qty),0) from virtual_inventory where is_deleted = false and sku_id = vi.sku_id and warehouse_id = vi.warehouse_id and virtual_warehouse_id = vi.virtual_warehouse_id and dict_inventory_status = 'frozen') as virtualFrozenQty, (select COALESCE(sum(qty),0) from inventory where is_deleted = false and sku_id = vi.sku_id and warehouse_id = vi.warehouse_id and dict_inventory_status = 'usable') as usableQty from virtual_inventory vi
${params.sqlMap.default} and vi.is_deleted = false
${params.permissionSql}
group by vi.sku_id,vi.warehouse_id,vi.virtual_warehouse_id order by
${item.field} ${item.sort}
vi.sku_id,vi.warehouse_id,vi.virtual_warehouse_id) diff where virtualQty > usableQty

SELECT vi.warehouse_id, vi.sku_id, vi.virtual_warehouse_id as toVirtualWarehouseId, COALESCE(sum(case when vi.dict_inventory_status = 'usable' then vi.qty else 0 end),0) as toVirtualWarehouseUsableQty FROM virtual_inventory vi WHERE vi.is_deleted = FALSE and vi.sku_id in
#{skuId}
and vi.warehouse_id in
#{warehouseId}
and vi.virtual_warehouse_id in
#{virtualWarehouseId}
GROUP BY vi.warehouse_id, vi.sku_id, vi.virtual_warehouse_id

select vi.warehouse_id, vi.sku_id, COALESCE(sum(vi.qty),0) as toVirtualWarehouseRealQty from virtual_inventory vi WHERE vi.is_deleted = FALSE and vi.sku_id in
#{skuId}
and vi.warehouse_id in
#{warehouseId}
GROUP BY vi.warehouse_id, vi.sku_id

select vi.sku_id, vi.warehouse_id, vi.virtual_warehouse_id, vi.dict_inventory_status, COALESCE(sum(vi.qty),0) as inventoryQty from virtual_inventory vi
vi.is_deleted = false and vi.sku_id in
#{item}
and vi.warehouse_id in
#{item}
and vi.virtual_warehouse_id in
#{item}
and vi.dict_inventory_status = #{params.dictInventoryStatus}
group by vi.sku_id,vi.warehouse_id,vi.virtual_warehouse_id,vi.dict_inventory_status

select COALESCE(sum(case when vi.dict_inventory_status = 'usable' then vi.qty else 0 end),0)
FROM virtual_inventory vi
WHERE vi.is_deleted = FALSE

  and vi.virtual_warehouse_id =#{params.virtualWarehouseId}


  and vi.virtual_warehouse_id =#{params.warehouseId}

GROUP BY vi.virtual_warehouse_id
